function extract(data) 
{
	data = (data.split("\n")).join("");

	var bmd = Bitmap.createBitmapData(1, 1);
    var output = bmd.getPixels(bmd.rect);
	output.clear();

	var dataBuffer = [];
	dataBuffer.length = 4;
	var outputBuffer = [];
	outputBuffer.length = 3;

	for( var i = 0; i < data.length; i += 4)
	{
		for( var j = 0; j < 4 && i + j < data.length; j++)
		{
			dataBuffer[j] = BASE64_CHARS.indexOf(data.charAt(i + j));
		}

		outputBuffer[0] = (dataBuffer[0] << 2) + ((dataBuffer[1] & 0x30) >> 4);   
		outputBuffer[1] = ((dataBuffer[1] & 0x0f) << 4) + ((dataBuffer[2] & 0x3c) >> 2);           
		outputBuffer[2] = ((dataBuffer[2] & 0x03) << 6) + dataBuffer[3];

		for( var k = 0; k < outputBuffer.length; k++)
		{
			if(dataBuffer[k+1] == 64)
				break;
			output.writeByte(outputBuffer[k]);
		}
	}

	output.inflate();

	output.position = 0;

	return output;
}

function loadBitmapData(width, height, raw) 
{
    var bmd = Bitmap.createBitmapData(width, height);
    bmd.setPixels(bmd.rect, extract(raw));
    return bmd;
}

function init()
{
	$.frameRate = 24;
	ScriptManager.clearTimer();
	ScriptManager.clearEl();
	ScriptManager.clearTrigger();
	Player.seek(0);
	Player.pause();
}

function createGameCanvas()
{
	gameCanvas = $.createCanvas({lifeTime:maxNum, x:0, y:0});
	gameCanvas.width = gameWidth;
	gameCanvas.height = gameHeight;

	gameCanvas.scaleX = 1;
}

function createScoreboard()
{
	format = $.createTextFormat( "Adobe 楷体 Std R", 35, 0xffff00, true, true, false);
	scoreboard = $.createComment("死亡次数：" + deadTime,{x:0, y:0, lifeTime:0, parent:gameCanvas});
	scoreboard.setTextFormat(format);
	scoreboard.defaultTextFormat = format;
	scoreboard.background = true;
	scoreboard.backgroundColor = 0x0000ff;
}

//删除换行，拆分空格
function modifyDanmu(danmu)
{
	var txt = danmu.text;
	txt = txt.replace("\r", "");
	txt = txt.replace("\n", "");
	txt = txt.replace("　", " ");
	danmu.text = txt;
	var texts = [];
	texts = txt.split(" ");
	if(texts.length == 1)
		return false;

	for(var i = texts.length - 1; i >= 0 ; i--)
	{
		if(texts[i] != "")
		{
			var newDanmu = {};
			newDanmu.text = texts[i];
			newDanmu.time = danmu.time;
			newDanmu.type = danmu.type;
			newDanmu.color = danmu.color;
			newDanmu.speed = danmu.speed;
			newDanmu.shape = danmu.shape;

			danmus.push(newDanmu);
		}
	}
	return true;
}

function initDanmus()
{
	for(var i = comments.length - 1; i >= 0 ; i--)
	{
		if(comments[i].text.substr(0, 2) == "/*")
			continue;

		if(comments[i].stime > endTime)
			continue;

		var danmu = {};
		danmu.text = comments[i].text;
		danmu.time = Math.floor(comments[i].stime * 1000);

		//字符长度，中日韩字符算2个长度
		var textLength = 0;
		for(var j = danmu.text.length - 1; j >= 0; j--)
		{
			if(danmu.text.charCodeAt(j) >= 0x3000 && danmu.text.charCodeAt(j) <= 0x9fff)
				textLength += 2;
			else
				textLength++;
		}

		//字符长度大于50直接无视
		if (textLength > 50)
		{
			danmu = null;
			continue;
		}

		danmu.type = -1;
		/*
			type 0 : 白色，横向移动
			type 1 : 随机色，横向移动
			type 2 : 随机色，横纵线性移动
			type 3 : 随机色，横纵线性移动，纵轴遇边缘反弹
			type 4 : 随机色，正弘曲线式移动
			type 5 : 随机色，横向纵向文本交错
			type 6 : 颜色持续变化，大小反复变化，横向移动
			type 7 : 随机色，大小随x轴变化
			type 8 : 随机色，抛物线带反弹
		*/
		if(danmu.time < stime0)
			danmu.type = 0; 
		else if(danmu.time < stime1)
			danmu.type = 1; 
		else if(danmu.time < stime2)
			danmu.type = 2; 
		else if(danmu.time < stime3)
			danmu.type = 3; 
		else if(danmu.time < stime4)
			danmu.type = 4; 
		else if(danmu.time < stime5)
			danmu.type = 5; 
		else if(danmu.time < stime6)
			danmu.type = 6; 
		else if(danmu.time < stime7)
			danmu.type = 7; 
		else if(danmu.time < stime8)
			danmu.type = 8;
		else
			danmu.type = 0;
		//字符长度大于25限定为type1，只能横向移动
		if(textLength > 25)
			danmu.type = 1;

		danmu.color = comments[i].color; //运行时错误
		danmu.speed = Utils.rand(5, 10);
		danmu.shape = {};

		if(modifyDanmu(danmu))
			danmu = null;
		else
			danmus.push(danmu);
	}
	flag = danmus.length - 1;

	danmus.sortOn("time", 16 | 2);
}

function captureNewDanmu()
{
	if(Player.commentList.length == numComments)
		return;

	for(var i = 0; i < Player.commentList.length - numComments; i++)
	{
		var danmu = {};
		var currentComment = Player.commentList[Player.commentList.length - 1 - i];
		danmu.text = currentComment.text;
		danmu.time = currentComment.stime * 1000;

		danmu.type = -1;
		if(danmu.time < stime0)
			danmu.type = 0; 
		else if(danmu.time < stime1)
			danmu.type = 1; 
		else if(danmu.time < stime2)
			danmu.type = 2; 
		else if(danmu.time < stime3)
			danmu.type = 3; 
		else if(danmu.time < stime4)
			danmu.type = 4; 
		else if(danmu.time < stime5)
			danmu.type = 5; 
		else if(danmu.time < stime6)
			danmu.type = 6; 
		else if(danmu.time < stime7)
			danmu.type = 7; 
		else
			danmu.type = 0;

		danmu.color = currentComment.color;
		danmu.speed = Utils.rand(5, 10);
		danmu.shape = $.createComment( danmu.text, {
				x:Player.width / gameScale,
				y:Utils.rand(0, gameHeight - 30),
				color:danmu.color,
				lifeTime: 0, 
				parent:gameCanvas
				});
		danmu.shape.border = true;
		danmu.shape.borderColor = 0x00ffff;

		danmus.push(danmu);
	}

	numComments = Player.commentList.length;
}

function createPlayer()
{
	var bmd = loadBitmapData(playerWidth, playerHeight, RAW_player);
	player.shape = Bitmap.createBitmap({bitmapData:bmd, parent:gameCanvas, lifeTime:0, scale:1.7});
	player.shape.x = 0;
	player.shape.y = 0;
	player.shape.remove();

	player.speed = 10;

	player.collisionBox = $.createShape({x:0, y:0, lifeTime:0, parent:gameCanvas, scale:1.7});
	player.collisionBox.graphics.beginFill(0xffffff);
	player.collisionBox.graphics.drawRect( player.shape.x + 19, player.shape.y + 7, 12, 4);
	player.collisionBox.graphics.endFill();
	player.collisionBox.visible = false;

	bmd = loadBitmapData(270, 45, RAW_explosion);
	player.explosions = [];
	for(var i = 5; i >= 0; i--) //0~5
	{
		var tempBmd = Bitmap.createBitmapData(45, 45, true);
		var rect = Bitmap.createRectangle( i * 45, 0, 45, 45);
		var point = $.createPoint(0, 0);
		tempBmd.copyPixels(bmd, rect, point);
		player.explosions[i] = Bitmap.createBitmap({bitmapData:tempBmd, lifeTime:0, parent:gameCanvas, scale:1.7});
		player.explosions[i].remove();
	}
	player.explosion = player.explosions[0];
	player.frameCounter = 0;
	player.index = 0;
	player.delay = 2;

	player.shield = $.createShape({x:0, y:0, lifeTime:0, parent:gameCanvas});
	player.shield.graphics.lineStyle(3, 0x00ffff);
	player.shield.graphics.drawCircle(player.shape.width >> 1, player.shape.height >> 1, 55 );
	player.shield.remove();

	player.keyDown = [];
	Player.keyTrigger(function(keyCode) {
		player.keyDown[keyCode] = true;
		}, maxNum);
	Player.keyTrigger(function(keyCode) {
		player.keyDown[keyCode] = false;
		}, maxNum, true);

	reborn();
}

function scaleGameCanvas()
{
	if(windowWidth == Player.width && windowHeight == Player.height)
		return;

	Player.pause();

	windowWidth = Player.width;
	windowHeight = Player.height;

	var scaleX = windowWidth / gameWidth;
	var scaleY = windowHeight / gameHeight;
	if(scaleX < scaleY)
		gameScale = scaleX;
	else
		gameScale = scaleY;
	gameCanvas.scaleX = gameScale; //此句不会执行，原因不明
	gameCanvas.scaleX = gameScale;
	gameCanvas.scaleY = gameScale;

	gameCanvas.x = Math.round((windowWidth - gameWidth * gameScale) >> 1);
	gameCanvas.y = Math.round((windowHeight - gameHeight * gameScale) >> 1);

}

function removeScrollComment()
{
	$.root.setChildIndex(gameCanvas, 0);

	for(var i = $.root.numChildren-2; i >= 1; i--) //1~$.root.numChildren-2
	{
		$.root.removeChildAt(i);
	}
}

function createCommentFields()
{
	if(flag < 0)
		return;

	var currentDanmu = danmus[flag];

	if( currentDanmu.time <= Player.time)
	{
		//当前弹幕太多时跳过
		if (displayingDanmus.length >= 50)
		{
			flag--;
			return;
		}

		//只在触发时执行一次
		currentDanmu.shape = $.createComment( currentDanmu.text, {lifeTime: 0, parent:gameCanvas});

		var danmuShape = currentDanmu.shape;

		switch( currentDanmu.type)
		{
			case 0:
				danmuShape.color = currentDanmu.color;
				danmuShape.x = Player.width / gameScale;
				danmuShape.y = Utils.rand(0, gameHeight - danmuShape.height);
				break;
			case 1:
				danmuShape.color = Utils.rand(0x000000, 0xffffff);
				danmuShape.x = Player.width / gameScale;
				danmuShape.y = Utils.rand(0, gameHeight - danmuShape.height);
				break;
			case 2:
				danmuShape.color = Utils.rand(0x000000, 0xffffff);
				danmuShape.x = Player.width / gameScale;
				danmuShape.y = Utils.rand(0, gameHeight - danmuShape.height);
				if(danmuShape.y <= gameHeight >> 1)
					currentDanmu.ySpeed = Utils.rand(0, 5);
				else
					currentDanmu.ySpeed = Utils.rand(-5, 0);
				break;
			case 3:
				danmuShape.color = Utils.rand(0x000000, 0xffffff);
				danmuShape.x = Player.width / gameScale;
				danmuShape.y = Utils.rand(0, gameHeight - danmuShape.height);
				currentDanmu.ySpeed = Utils.rand(-7, 7);
				break;
			case 4:
				danmuShape.color = Utils.rand(0x000000, 0xffffff);
				danmuShape.x = Player.width / gameScale;
				danmuShape.y = Utils.rand(0, gameHeight - danmuShape.height);
				currentDanmu.amplitude = Utils.rand(0, 10); //振幅
				break;
			case 5:
				danmuShape.color = Utils.rand(0x000000, 0xffffff);

				currentDanmu.lengthways = Math.round( Math.random());
				if( currentDanmu.lengthways)
				{
					danmuShape.wordWrap = true; //设置自动换行
					danmuShape.multiline = true; //允许多行
					danmuShape.width = 30; //有待调整

					danmuShape.x = Utils.rand(0, gameWidth - danmuShape.width);
					danmuShape.y = -danmuShape.height / gameScale;
				}
				else
				{
					danmuShape.x = Player.width / gameScale;
					danmuShape.y = Utils.rand(0, gameHeight - danmuShape.height);
				}
				break;
			case 6:
				danmuShape.x = Player.width / gameScale;
				danmuShape.y = Utils.rand(0, gameHeight - danmuShape.height);
				currentDanmu.subType = Math.floor(Utils.rand(0, 64)); //b000 000~b111 111
				currentDanmu.r = Math.floor(Utils.rand(0, 256));
				currentDanmu.g = Math.floor(Utils.rand(0, 256));
				currentDanmu.b = Math.floor(Utils.rand(0, 256));
				currentDanmu.color = Utils.rgb(currentDanmu.r, currentDanmu.g, currentDanmu.b);
				break;
			case 7:
				danmuShape.x = Player.width / gameScale;
				danmuShape.y = Utils.rand(0, gameHeight - danmuShape.height);
				currentDanmu.offset = Utils.rand(0, 100);
				danmuShape.color = Utils.rand(0x000000, 0xffffff);
				break;
			case 8:
				danmuShape.x = Player.width / gameScale;
				danmuShape.y = gameHeight - danmuShape.width;
				danmuShape.color = Utils.rand(0x000000, 0xffffff);
				currentDanmu.ySpeed = Utils.rand(-20, -10);
		}

		displayingDanmus.push(currentDanmu);
		numDanmu++;
		flag--;
	}
}

function moveDanmus()
{
	for(var i = displayingDanmus.length - 1; i >= 0 ; i--)
	{
		var currentDanmu = displayingDanmus[i];
		var danmuShape = currentDanmu.shape;
		if(danmuShape.x + gameCanvas.x + 50 < -danmuShape.width)
		{
			gameCanvas.removeChild(danmuShape);
			currentDanmu = null;
			displayingDanmus.splice(i, 1);
			break;
		}

		switch(currentDanmu.type)
		{
			case 0:
			case 1:
				danmuShape.x -= currentDanmu.speed;
				break;
			case 2:
				danmuShape.x -= currentDanmu.speed;
				if(danmuShape.x <= gameWidth)
					danmuShape.y += currentDanmu.ySpeed;
				break;
			case 3:
				danmuShape.x -= currentDanmu.speed;
				danmuShape.y += currentDanmu.ySpeed;
				if(danmuShape.y <= 0 || danmuShape.y >= gameHeight - danmuShape.height)
					currentDanmu.ySpeed *= -1;
				break;
			case 4:
				danmuShape.x -= currentDanmu.speed;
				danmuShape.y += Math.sin(danmuShape.x / 100) * currentDanmu.amplitude;
				break;
			case 5:
				if(danmuShape.multiline)
				{
					if(danmuShape.y  > gameHeight)
					{
						gameCanvas.removeChild(danmuShape);
						currentDanmu = null;
						displayingDanmus.splice(i, 1);
						break;
					}

					danmuShape.y += currentDanmu.speed;
				}
				else
					danmuShape.x -= currentDanmu.speed;
				break;
			case 6:
				danmuShape.x -= currentDanmu.speed;
				if(currentDanmu.subType & 32) //32=b100 000
				{
					if(currentDanmu.subType & 16) //16=b010 000
					{
						currentDanmu.r += 10;
						if(currentDanmu.r > 255)
						{
							currentDanmu.r = 255;
							currentDanmu.subType ^= 16;
						}
					}
					else
					{
						currentDanmu.r -= 10;
						if(currentDanmu.r < 0)
						{
							currentDanmu.r = 0;
							currentDanmu.subType ^= 16;
						}
					}
				}

				if(currentDanmu.subType & 8) //8=b001 000
				{
					if(currentDanmu.subType & 4) //4=b000 100
					{
						currentDanmu.g += 10;
						if(currentDanmu.g > 255)
						{
							currentDanmu.g= 255;
							currentDanmu.subType ^= 4;
						}
					}
					else
					{
						currentDanmu.g -= 10;
						if(currentDanmu.g < 0)
						{
							currentDanmu.g = 0;
							currentDanmu.subType ^= 4;
						}
					}
				}

				if(currentDanmu.subType & 2) //2=b000 010
				{
					if(currentDanmu.sybType & 1) //1=b000 001
					{
						currentDanmu.b += 10;
						if(currentDanmu.b > 255)
						{
							currentDanmu.b= 255;
							currentDanmu.subType ^= 1;
						}
					}
					else
					{
						currentDanmu.b -= 10;
						if(currentDanmu.b < 0)
						{
							currentDanmu.b = 0;
							currentDanmu.subType ^= 1;
						}
					}
				}
				danmuShape.color = currentDanmu.r << 16 | currentDanmu.g << 8 | currentDanmu.b;
				break;
			case 7:
				danmuShape.x -= currentDanmu.speed;
				var sinX = 0.75 * Math.sin(danmuShape.x / 100 + currentDanmu.offset) + 0.5;
				danmuShape.scaleX = sinX + 1;
				danmuShape.scaleY = sinX + 1;
				break;
			case 8:
				if(danmuShape.y >= gameHeight - danmuShape.height)
					currentDanmu.ySpeed *= -1;
				danmuShape.x -= currentDanmu.speed;
				danmuShape.y += currentDanmu.ySpeed;
				currentDanmu.ySpeed += gravity;				
		}
	}
}

function movePlayer()
{
	var newX = 0;
	var newY = 0;
	var shape = player.shape;
	if (player.keyDown[Keyboard.W ^ 0]) 
	{
		newY = shape.y - player.speed;
		if(newY < 0)
			shape.y = 0;
		else
			shape.y = newY;
	}
	if (player.keyDown[Keyboard.S ^ 0]) 
	{
		newY = shape.y + player.speed;
		if(newY > gameHeight - shape.height)
			shape.y = gameHeight - shape.height;
		else
			shape.y = newY;
	}
	if (player.keyDown[Keyboard.A ^ 0])
	{
		newX = shape.x - player.speed;
		if(newX < 0)
			shape.x = 0;
		else
			shape.x = newX;
	}
	if (player.keyDown[Keyboard.D ^ 0]) 
	{
		newX = shape.x + player.speed;
		if(newX > gameWidth - shape.width)
			shape.x = gameWidth - shape.width;
		else
			shape.x = newX;
	}

	player.collisionBox.visible = false; //防止拖动进度条后显示进度条
	player.collisionBox.x = shape.x;
	player.collisionBox.y = shape.y;

	if(indestructible)
	{
		player.shield.x = shape.x;
		player.shield.y = shape.y;
	}
}

function updataScoreboard()
{
	scoreboard.text = "死亡次数：" + deadTime;
}

function checkCollision()
{
	if(indestructible)
	{
		for(var i = displayingDanmus.length - 1; i >=0; i--)
		{
			if((player.shield).hitTestObject(displayingDanmus[i].shape))
			{
				displayingDanmus[i].shape.remove();
				displayingDanmus[i] = null;
				displayingDanmus.splice(i, 1);
			}
		}
	}
	else
	{
		for(var i = displayingDanmus.length - 1; i >=0; i--)
		{
			if((player.collisionBox).hitTestObject(displayingDanmus[i].shape))
			{
				alive = false;
				displayingDanmus[i].shape.remove();
				displayingDanmus[i] = null;
				displayingDanmus.splice(i, 1);
				deadTime++;
				updataScoreboard();
				return;
			}
		}
	}
}

function removeShield()
{
	player.shield.remove();
	indestructible = false;
}

function reborn()
{
	player.shape.x = 0;
	player.shape.y = (gameHeight - player.shape.height) >> 1;

	gameCanvas.addChild(player.shape);
	alive = true;
	indestructible = true;

	player.shield.x = 0;
	player.shield.y = player.shape.y;
	gameCanvas.addChild(player.shield);
	timer(removeShield, 2000);
}

function die()
{
	if(player.frameCounter >= player.delay)
		player.frameCounter = 0;

	if(player.frameCounter == 0)
	{
		if(player.index == 0)
		{
			player.shape.remove();
		}
		else
		{
			player.explosion.remove();
		}

		if(player.index == 6)
		{
			reborn();
			player.index = 0;
		}
		else
		{
			var index = player.index;
			player.explosion = player.explosions[index];
			player.explosion.x = player.shape.x;
			player.explosion.y = player.shape.y - 18;
			gameCanvas.addChild(player.explosion);
			player.index++;
		}
	}

	player.frameCounter++;
}

function timeJumped()
{
	if(Player.time - playTime > 10000 || playTime - Player.time > 10000)
	{
		Player.seek(playTime);
		return true;
	}
	else
	{
		playTime = Player.time;
		return false;
	}
}

function end()
{
	Global._set("deadTime", deadTime);
	Global._set("numDanmu", numDanmu);

	$.root.removeEventListener("enterFrame", mainLoop);
	ScriptManager.clearTimer();
	ScriptManager.clearEl();
	ScriptManager.clearTrigger();
}

function mainLoop()
{
	scaleGameCanvas();

	if(Player.state != "playing")
		return;
	if(timeJumped())
		return;

	if(Player.time > endTime)
	{
		end();
		return;
	}

	removeScrollComment();
	createCommentFields();
	moveDanmus();

	if(alive)
	{
		movePlayer();
		checkCollision();
	}
	else
	{
		die();
	}
}

function main()
{
	init();
	createGameCanvas();
	createScoreboard();
	initDanmus();
	createPlayer();
	$.root.addEventListener("enterFrame", mainLoop);
	Utils.interval(captureNewDanmu, 1000, 0);
}

main();

