function createScoreboard()
{
	var deadTime = Global._get("deadTime");
	var numDanmu = Global._get("numDanmu");

	scoreboard = $.createComment("您的成绩\n死亡次数：" + deadTime + "\n弹幕数量：" + numDanmu, {x:0, y:0, lifeTime:2147483647});
	scoreboard.textColor = 0xffff00;
	scoreboard.background = true;
	scoreboard.backgroundColor = 0x0000ff;
}

function init()
{
	ScriptManager.clearTimer();
	ScriptManager.clearEl();
	ScriptManager.clearTrigger();
}

function adjustPosition()
{
	$.root.setChildIndex(mainCanvas, $.root.numChildren-1);
	$.root.setChildIndex(scoreboard, $.root.numChildren-1);

	if(windowWidth == Player.width && windowHeight == Player.height)
		return;

	windowWidth = Player.width;
	windowHeight = Player.height;

	mainCanvas.x = (windowWidth - mainCanvas.width) / 2;
	mainCanvas.y = windowHeight / 2 + 25;

	scoreboard.x = (windowWidth - scoreboard.width) / 2;
	scoreboard.y = windowHeight / 2 - scoreboard.height - 25;

	blackCurtain.width = windowWidth;
	blackCurtain.height = windowHeight;
}

function main()
{
	init();
	createBlackCurtain();
	createMainCanvas();
	createScoreboard();
	$.root.addEventListener("enterFrame", adjustPosition);
}

main();
